{"path": "/app/decompress.py", "content": "#!/usr/bin/env python3
import argparse
import json
import os
import sys
from typing import Dict, List

CHUNK_SIZE = 15_000_000
BASE = 30
MANIFEST_NAME = "reshard_manifest.json"


def _chunk_relpath(chunk_id: int, depth: int, base: int) -> str:
    digits: List[int] = []
    remaining = chunk_id
    for _ in range(depth):
        digits.append(remaining % base)
        remaining //= base
    if remaining != 0:
        raise ValueError(f"Chunk id {chunk_id} exceeds depth {depth}")
    digits.reverse()
    dir_parts = [f"d{digit:02d}" for digit in digits[:-1]]
    filename = f"c{digits[-1]:02d}.bin"
    return os.path.join(*dir_parts, filename) if dir_parts else filename


def _load_manifest(resharded_dir: str) -> Dict:
    manifest_path = os.path.join(resharded_dir, MANIFEST_NAME)
    if not os.path.isfile(manifest_path):
        raise RuntimeError(f"Manifest not found: {manifest_path}")
    with open(manifest_path, "r", encoding="utf-8") as handle:
        manifest = json.load(handle)
    return manifest


def _validate_manifest(manifest: Dict) -> None:
    if manifest.get("version") != 1:
        raise RuntimeError("Unsupported manifest version")
    if "files" not in manifest or "dirs" not in manifest:
        raise RuntimeError("Manifest missing required fields")


def _ensure_dirs(resharded_dir: str, dirs: List[str]) -> None:
    for rel_dir in dirs:
        if not rel_dir:
            continue
        abs_dir = os.path.join(resharded_dir, rel_dir)
        os.makedirs(abs_dir, exist_ok=True)


def _restore_files(resharded_dir: str, manifest: Dict) -> None:
    depth = manifest["depth"]
    base = manifest["base"]
    chunk_size = manifest["chunk_size"]
    data_dir = os.path.join(resharded_dir, manifest.get("data_dir", "reshard_data"))

    for entry in manifest["files"]:
        rel_path = entry["path"]
        size = entry["size"]
        start_chunk = entry["start_chunk"]
        chunk_count = entry["chunk_count"]
        abs_path = os.path.join(resharded_dir, rel_path)
        os.makedirs(os.path.dirname(abs_path) or resharded_dir, exist_ok=True)
        with open(abs_path, "wb") as target:
            bytes_remaining = size
            for offset in range(chunk_count):
                chunk_id = start_chunk + offset
                rel_chunk = _chunk_relpath(chunk_id, depth, base)
                abs_chunk = os.path.join(data_dir, rel_chunk)
                if not os.path.isfile(abs_chunk):
                    raise RuntimeError(f"Missing chunk file: {abs_chunk}")
                with open(abs_chunk, "rb") as source:
                    while True:
                        data = source.read(1024 * 1024)
                        if not data:
                            break
                        if bytes_remaining <= 0:
                            raise RuntimeError(
                                f"Chunk data exceeds expected size for {rel_path}"
                            )
                        if len(data) > bytes_remaining:
                            data = data[:bytes_remaining]
                        target.write(data)
                        bytes_remaining -= len(data)
                if bytes_remaining <= 0:
                    break
            if bytes_remaining != 0:
                raise RuntimeError(f"File {rel_path} incomplete after restore")

        if size == 0:
            # create empty file explicitly (open already did)
            pass


def _cleanup_resharded(resharded_dir: str, manifest: Dict) -> None:
    data_dir = os.path.join(resharded_dir, manifest.get("data_dir", "reshard_data"))
    if os.path.isdir(data_dir):
        for root, dirnames, filenames in os.walk(data_dir, topdown=False):
            for name in filenames:
                os.remove(os.path.join(root, name))
            for name in dirnames:
                os.rmdir(os.path.join(root, name))
        os.rmdir(data_dir)
    manifest_path = os.path.join(resharded_dir, MANIFEST_NAME)
    if os.path.isfile(manifest_path):
        os.remove(manifest_path)


def decompress(resharded_dir: str) -> None:
    if not os.path.isdir(resharded_dir):
        raise RuntimeError(f"Resharded directory not found: {resharded_dir}")

    manifest = _load_manifest(resharded_dir)
    _validate_manifest(manifest)
    if manifest.get("chunk_size") != CHUNK_SIZE or manifest.get("base") != BASE:
        raise RuntimeError("Manifest settings do not match script defaults")

    _ensure_dirs(resharded_dir, manifest["dirs"])
    _restore_files(resharded_dir, manifest)
    _cleanup_resharded(resharded_dir, manifest)


def main() -> None:
    parser = argparse.ArgumentParser(description="Restore a resharded dataset in-place.")
    parser.add_argument("resharded_dir", help="Directory containing resharded data")
    args = parser.parse_args()
    decompress(args.resharded_dir)


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)
"}

